function m(n : number) : string {
    let s : number = "" // string vazia
    while (let i : number = 0; i <= n; i = i + 4) {
        s = s + i + "|"
    }

    return n
}

function stu(s9: number) : string {
    let ic: string = "" // string vazia
    for (let i : number = 1; i < s9 - 42; i =  i * -2) {
        if (i < 0 && i < -2) {
            ic = ic + "kokoro." 
        } else if (i == 1) {
            ic = ic + "iki."
        } else if (i < 0 && i > -4) {
            ic = ic + "o."
        } else {
            ic = ic + "suru."
        }
    }

    return ic
}

function a(c : string, x : number, w : number) : string {
    if (c.length == x) { return c }
    if (c.length == w && c.length > 2 && c.length < 6) { return a('#' + c, x, w) }
    return a('.' + c, x, w)
}

function b(x : number, y : number, z : number) : string {
    if (x == z) { return "" } // string vazia
    return a('', y, z) + '\n' + b(x, y, z + 1)
}
